mapper.select:
select sum(re.score) from sys_result re,sys_task ta where re.is_finish = 1
and re.p_id = #{pId} and ta.p_id = #{pId}
and ta.category = #{category} and re.task_id = ta.id and re.u_id in

    #{id}

GROUP BY re.u_id

select p_id from sys_result where u_id = #{uId} and is_finish = 1
and p_id = #{pId}
and date_format(create_time,'%Y') = #{year}

select sum(score) from sys_result where p_id = #{pId} and u_id in

    #{id}

GROUP BY u_id

select a.id, b.title ,b.id as projectId, b.start_time ,b.end_time, d.user_name, d.nick_name
,c.task_name,c.category,c.id as taskId,a.score
,d.user_id, c.score as highScore
from sys_result a
inner join sys_project b on a.p_id=b.id
inner join sys_task c on a.task_id=c.selectTaskByProjectAndTeacher
inner join sys_user d on a.u_id=d.user_id

    and b.title =#{title}
    and c.task_name =#{taskName}
    and c.category =#{taskCategory}

select a.id, a.evidence ,b.title ,b.id as projectId, b.start_time ,b.end_time, d.user_name, d.nick_name
,c.task_name,c.category,c.id as taskId,a.score
,d.user_id, c.score as highScore
from sys_result a
inner join sys_project b on a.p_id=b.id
inner join sys_task c on a.task_id=c.id
inner join sys_user d on a.u_id=d.user_id

    and b.id =#{projectId}
    and c.task_name =#{taskName}
    and a.u_id = #{userId}
    and c.category =#{taskCategory}
    and a.score >= #{limitScore}

select sum(re.score)
from sys_role r
         left join sys_user_role ur on ur.role_id = r.role_id
         left join sys_user u on u.user_id = ur.user_id
         left join sys_result re on re.u_id = re.u_id
         left join sys_task ta on re.task_id = ta.id
where r.role_desc = #{department}
  and re.p_id = #{pId}
  and ta.category = #{category}
GROUP BY r.role_name

select sum(re.score)
from sys_role r
         left join sys_user_role ur on ur.role_id = r.role_id
         left join sys_user u on u.user_id = ur.user_id
         left join sys_result re on re.u_id = re.u_id
         left join sys_task ta on re.task_id = ta.id
  and re.p_id = #{pId}
  and ta.category = #{category}
  and re.u_id = #{teacherId}
GROUP BY r.role_name

update.foreach:
update sys_result a

    score=#{item.score}
    where
    a.u_id=#{item.userId} and a.p_id=#{item.projectId} and a.task_id=#{item.taskId}
